        /// <summary>dir(): Typhon has no run-time view of the caller's local names; the list is empty.</summary>
        public static List<string> dir() => new List<string>();

        /// <summary>
        /// dir(obj): the sorted attribute names of an object (its class's fields, properties and methods, attributes set at
        /// run time) or of a class (its members). For str, list, dict, ...: their Python methods. Python's dunder methods
        /// that the object's class does not define itself (__class__, __eq__ of object, ...) are not listed.
        /// </summary>
        public static List<string> dir(object? o)
        {
            var names = new HashSet<string>(StringComparer.Ordinal);
            if (o == null) { foreach (var n in new[] { "__bool__", "__class__", "__doc__", "__eq__", "__hash__", "__repr__" }) names.Add(n); return Sorted(names); }
            if (o is Type t)
            {
                foreach (var n in Members(t, BindingFlags.Public | BindingFlags.Static | BindingFlags.Instance)) names.Add(n);
                names.Add("__name__"); names.Add("__doc__"); names.Add("__module__");
                return Sorted(names);
            }
            var type = o.GetType();
            if (IsPythonClass(type)) foreach (var n in Members(type, BindingFlags.Public | BindingFlags.Instance | BindingFlags.Static)) names.Add(n);
            if (o is PyFunction pf)
            {
                foreach (var n in new[] { "__call__", "__doc__", "__module__", "__name__", "__qualname__", "__wrapped__" }) names.Add(n);
                if (pf._attrs != null) foreach (var n in pf._attrs.Keys) names.Add(n);
            }
            else
            {
                foreach (var kv in new PyAttrDict(o)) names.Add(kv.Key);
                if (o is System.Dynamic.DynamicObject dyn) foreach (var n in dyn.GetDynamicMemberNames()) names.Add(n);
                // str, list, dict, ...: the Python methods the runtime gives them (extension methods on their type)
                foreach (var n in ExtensionNames(type)) names.Add(n);
                if (!IsPythonClass(type) && names.Count == 0) foreach (var n in Members(type, BindingFlags.Public | BindingFlags.Instance)) names.Add(n);
            }
            return Sorted(names);
        }

        static List<string> Sorted(HashSet<string> names) { var l = names.ToList(); l.Sort(StringComparer.Ordinal); return l; }

        static bool IsPythonClass(Type t) => !(t.Namespace is string ns && (ns == "System" || ns.StartsWith("System.") || ns.StartsWith("Microsoft.")));

        /// <summary>The Python-visible members of a class: no accessors, operators, compiler-generated or .NET object members.</summary>
        static IEnumerable<string> Members(Type t, BindingFlags flags)
        {
            var objectMembers = new HashSet<string> { "Equals", "GetHashCode", "GetType", "ToString", "Finalize", "MemberwiseClone", "Deconstruct", "GetEnumerator", "CompareTo", "Dispose" };
            foreach (var m in t.GetMembers(flags))
            {
                string n = m.Name;
                if (m is MethodInfo mi && (mi.IsSpecialName || mi.IsDefined(typeof(PyMissingMethodAttribute), false))) continue;
                if (m is ConstructorInfo || m is EventInfo) continue;
                if (m is Type) continue;
                if (n.Contains('<') || n.Contains('.') || n.StartsWith("__decorated_") || n.StartsWith("__py_") || objectMembers.Contains(n)) continue;
                if (m.DeclaringType == typeof(object) || m.DeclaringType == typeof(Exception) || m.DeclaringType == typeof(System.Dynamic.DynamicObject)) continue;
                // overrides of .NET's own virtual methods (DynamicObject.TryGetMember, Exception.Message, ...)
                if (m is MethodInfo vm && vm.GetBaseDefinition().DeclaringType is Type bd && !IsPythonClass(bd)) continue;
                if (m is PropertyInfo vp && (vp.GetMethod ?? vp.SetMethod)?.GetBaseDefinition().DeclaringType is Type pd && !IsPythonClass(pd)) continue;
                if (m is PropertyInfo pi && pi.GetIndexParameters().Length > 0) continue;
                yield return n;
            }
        }

        static readonly Dictionary<Type, string[]> _extensionNames = new Dictionary<Type, string[]>();

        /// <summary>The names of the runtime's extension methods (str.upper, list.append, ...) that apply to a type.</summary>
        static string[] ExtensionNames(Type type)
        {
            lock (_extensionNames)
            {
                if (_extensionNames.TryGetValue(type, out var cached)) return cached;
                var names = new HashSet<string>(StringComparer.Ordinal);
                foreach (var m in typeof(Builtins).GetMethods(BindingFlags.Public | BindingFlags.Static))
                {
                    if (!m.IsDefined(typeof(ExtensionAttribute), false) || m.Name.StartsWith("__") || m.Name.Contains('<')) continue;
                    var p = m.GetParameters()[0].ParameterType;
                    bool applies = p.IsAssignableFrom(type);
                    if (!applies && p.ContainsGenericParameters)
                    {
                        var def = p.IsGenericType ? p.GetGenericTypeDefinition() : null;
                        applies = def != null && (Ancestors(type).Any(a => a.IsGenericType && a.GetGenericTypeDefinition() == def) ||
                                                  type.GetInterfaces().Any(i => i.IsGenericType && i.GetGenericTypeDefinition() == def));
                    }
                    if (applies && p != typeof(object)) names.Add(m.Name);
                }
                return _extensionNames[type] = names.ToArray();
            }
        }

