        /// <summary>
        /// __import__(name, globals=None, locals=None, fromlist=(), level=0): a Typhon standard module by name, as the class
        /// that holds its members (getattr(m, "sqrt") works on it). Without fromlist, a dotted name gives the top-level
        /// package, like Python's. Typhon modules of the program itself are compiled in: import them with import.
        /// </summary>
        public static object __import__(object? name, object? globals = null, object? locals = null, object? fromlist = null, long level = 0)
        {
            if (name is not string moduleName) throw new InvalidCastException("module name must be a string");
            if (level != 0) throw new NotImplementedException("__import__() with a relative level is not supported");
            var parts = moduleName.Split('.');
            bool wantsLeaf = fromlist is IEnumerable fl && fl.Cast<object?>().Any();
            Type? top = StdlibModuleType(parts[0]);
            if (top == null || PyModule.CompiledType(moduleName) != null)
            {
                object loaded = Typhon.Stdlib.SourceImport.ImportModule(moduleName);
                return wantsLeaf || parts.Length == 1 ? loaded : Typhon.Stdlib.SourceImport.ImportModule(parts[0]);
            }
            Type current = top;
            for (int i = 1; i < parts.Length; i++)
            {
                current = current.GetNestedType(parts[i], BindingFlags.Public | BindingFlags.NonPublic) ?? current.GetNestedType(parts[i] + "_", BindingFlags.Public | BindingFlags.NonPublic)
                    ?? throw new ModuleNotFoundError($"No module named '{string.Join(".", parts.Take(i + 1))}'", string.Join(".", parts.Take(i + 1)));
            }
            return wantsLeaf ? current : top;
        }

        /// <summary>The class of a Typhon standard module: Typhon.Stdlib.name or name_ (math → math_), in any loaded assembly.</summary>
        internal static Type? StdlibModuleType(string name)
        {
            foreach (var candidate in new[] { "Typhon.Stdlib." + name, "Typhon.Stdlib." + name + "_" })
            {
                if (typeof(Builtins).Assembly.GetType(candidate) is Type own) return own;
                foreach (var asm in AppDomain.CurrentDomain.GetAssemblies())
                    if (asm.GetType(candidate) is Type t) return t;
            }
            return null;
        }

