        /// <summary>frozendict(): an empty immutable dict.</summary>
        public static frozendict<object, object?> frozendict() => new frozendict<object, object?>(Array.Empty<KeyValuePair<object, object?>>(), PyKeyComparer.Instance!);
        /// <summary>frozendict(mapping): an immutable copy, in the mapping's order.</summary>
        public static frozendict<K, V> frozendict<K, V>(IDictionary<K, V> mapping) where K : notnull => new frozendict<K, V>(mapping, FrozenComparer<K>());
        public static frozendict<K, V> frozendict<K, V>(IEnumerable<(K, V)> pairs) where K : notnull =>
            new frozendict<K, V>(pairs.Select(p => new KeyValuePair<K, V>(p.Item1, p.Item2)), FrozenComparer<K>());
        /// <summary>frozendict(a=1, b=2) / frozendict(mapping, c=3).</summary>
        public static frozendict<object, object?> frozendict(IDictionary<string, object?> __kwargs) => frozendict(null, __kwargs);
        public static frozendict<object, object?> frozendict(object? mapping, IDictionary<string, object?> __kwargs)
        {
            var items = mapping != null ? ReadDictItems(mapping) : Enumerable.Empty<KeyValuePair<object, object?>>();
            var keywordItems = __kwargs.Select(item => new KeyValuePair<object, object?>(item.Key, item.Value));
            return new frozendict<object, object?>(items.Concat(keywordItems), PyKeyComparer.Instance!);
        }

        static IEqualityComparer<K> FrozenComparer<K>() where K : notnull =>
            typeof(K) == typeof(object) ? (IEqualityComparer<K>)(object)PyKeyComparer.Instance : EqualityComparer<K>.Default;
    }

    /// <summary>
    /// frozendict (CPython 3.15): an immutable, hashable dict. It keeps insertion order, compares equal to a dict with the
    /// same items, hashes like frozenset(d.items()), and | makes a new frozendict. Assignment and the mutating methods
    /// raise TypeError / AttributeError. (It is an OrderedDictionary, so it reads like a dict everywhere one is expected.)
    /// </summary>
    internal sealed class frozendict<K, V> : OrderedDictionary<K, V>, IPyRepr, IDictionary, IDictionary<K, V> where K : notnull
    {
        int? _hash;
        public frozendict(IEnumerable<KeyValuePair<K, V>> items, IEqualityComparer<K> comparer) : base(comparer)
        {
            foreach (var kv in items) base[PyNoneDictKey.Store(kv.Key)] = kv.Value;
        }

        static Exception ReadOnly() => new InvalidCastException("'frozendict' object does not support item assignment");
        static Exception DeletionNotSupported() => new InvalidCastException("'frozendict' object doesn't support item deletion");
        static Exception NoAttribute(string name) => new MissingMemberException($"'frozendict' object has no attribute '{name}'");

        public new V this[K key]
        {
            get => base[key];
            set => throw ReadOnly();
        }
        object? IDictionary.this[object key]
        {
            get => key is K typedKey && base.TryGetValue(typedKey, out V? value) ? value : null;
            set => throw ReadOnly();
        }
        bool IDictionary.IsReadOnly => true;
        bool IDictionary.IsFixedSize => true;
        void IDictionary.Add(object key, object? value) => throw ReadOnly();
        void IDictionary.Remove(object key) => throw DeletionNotSupported();
        void IDictionary.Clear() => throw NoAttribute("clear");
        bool ICollection<KeyValuePair<K, V>>.IsReadOnly => true;
        void ICollection<KeyValuePair<K, V>>.Add(KeyValuePair<K, V> item) => throw ReadOnly();
        bool ICollection<KeyValuePair<K, V>>.Remove(KeyValuePair<K, V> item) => throw DeletionNotSupported();

        public new void Add(K key, V value) => throw ReadOnly();
        public new bool Remove(K key) => throw DeletionNotSupported();
        public new void Clear() => throw NoAttribute("clear");
        public void update(object? other = null) => throw NoAttribute("update");
        public V pop(K key) => throw NoAttribute("pop");
        public (K, V) popitem() => throw NoAttribute("popitem");
        public V setdefault(K key, V value = default!) => throw NoAttribute("setdefault");
        public void __setitem__(K key, V value) => throw ReadOnly();
        public void __delitem__(K key) => throw DeletionNotSupported();

        /// <summary>copy(): a frozendict is immutable, so the copy is the object itself.</summary>
        public frozendict<K, V> copy() => this;
        public object? get(object? key, object? @default = null) =>
            Builtins.KeyFor((IDictionary)this, key) is K stored && base.TryGetValue(stored, out V? value)
                ? value : @default;

        public static frozendict<K, object?> fromkeys(IEnumerable<K> keys, object? value = null) =>
            new frozendict<K, object?>(keys.Select(k => new KeyValuePair<K, object?>(k, value)), typeof(K) == typeof(object) ? (IEqualityComparer<K>)(object)PyKeyComparer.Instance : EqualityComparer<K>.Default);

        public static frozendict<K, V> operator |(frozendict<K, V> a, IDictionary<K, V> b) => new frozendict<K, V>(a.Concat(b), a.Comparer);
        public frozendict<K, V> __or__(IDictionary<K, V> other) => this | other;

        /// <summary>hash(fd): order-independent, from the items (like frozenset(fd.items())); unhashable values raise TypeError.</summary>
        public override int GetHashCode()
        {
            if (_hash is int h) return h;
            int acc = 0x345678;
            foreach (var kv in (OrderedDictionary<K, V>)this)
            {
                if (kv.Value is IList || kv.Value is IDictionary && kv.Value is not IPyRepr || kv.Value is ISet<object>)
                    throw new InvalidCastException($"unhashable type: '{Builtins.PyTypeName(kv.Value!.GetType())}'");
                acc ^= HashCode.Combine(Builtins.KeyHash(kv.Key), Builtins.KeyHash(kv.Value)) * 1000003;
            }
            _hash = acc;
            return acc;
        }
        public long __hash__() => GetHashCode();
        public override bool Equals(object? obj) => obj is IDictionary && Builtins.eq(this, obj);

        public string __repr__() => Count == 0 ? "frozendict()" :
            "frozendict({" + string.Join(", ", ((OrderedDictionary<K, V>)this).Select(kv => Builtins.repr(kv.Key) + ": " + Builtins.repr(kv.Value))) + "})";
        public override string ToString() => __repr__();
    }
}
